local _, addon = ...
addon.localeData.frFR.ambient = {
    GNOME = { "Mon bouclier n'est pas trop petit. Le monde est simplement mal proportionné.", "*sort une minuscule clé de son gant et resserre un écrou.*", "Si le mécanisme grince, ce n'est pas une panne. C'est un retour d'information.", "*essaie de mesurer une bosse dans son casque au millimètre près.*", "Un plan n'est complet que lorsqu'un imbécile le traverse en hurlant.", "*note un chiffre sur son bouclier, puis l'efface aussitôt.*", "Tout sur mon armure est intentionnel. Surtout ce qui fume encore.", "*tapote deux fois un petit avertisseur bricolé.*" },
    HUMAN = { "Le silence d'avant la bataille est pire que son vacarme.", "*passe un doigt sur le blason décoloré de son bouclier.*", "Ceux qui se tiennent près de moi rentreront aussi à mes côtés.", "*vérifie une dernière fois les sangles d'un compagnon.*", "Un plan de bataille n'est que du papier avant le premier pas.", "*redresse les rangs d'un regard et d'un geste.*", "Mon père disait : sois courageux. Ma mère : reviens vivant.", "*resserre ses gants et contemple l'horizon.*" },
    DWARF = { "Un guerrier sans barbe n'a aucune excuse pour être aussi lent.", "*retire une miette de pain de sa barbe et la regarde avec méfiance.*", "J'ai gagné le dernier combat. Pas la dernière chope, hélas.", "*polit une entaille de sa hache jusqu'à la rendre presque présentable.*", "Qui trouve les nains têtus n'a jamais négocié avec une montagne.", "*secoue la sangle de son bouclier en maugréant sur les mauvais artisans.*", "Si nous survivons, j'offre une tournée. Sinon, quel gâchis de bière !", "*écoute attentivement si une bouteille tinte dans son sac.*" },
    NIGHTELF = { "Certains arbres que j'ai connus étaient vieux avant que ce royaume ait un nom.", "*suit du doigt un motif de feuille gravé sur son arme.*", "Le sang s'efface. Le souvenir de la raison du combat demeure.", "*s'immobilise un instant pour écouter la forêt.*", "Un pas silencieux protège parfois plus qu'une victoire bruyante.", "*retire doucement une feuille de son épaule et la laisse partir.*", "La nuit n'est pas calme aujourd'hui. Je la respecterai malgré tout.", "*regarde longtemps la dernière lumière entre les branches.*" },
    DRAENEI = { "J'ai déjà perdu une patrie. Je n'en abandonnerai pas facilement une autre.", "*effleure un petit souvenir fixé à son armure.*", "L'espoir n'a pas besoin d'être crié pour être porté.", "*place son bouclier afin que quelqu'un puisse encore s'y abriter.*", "Parfois, le courage n'est qu'un pas de plus malgré la peur.", "*ferme brièvement les yeux pour rassembler ses pensées.*", "Ceux qui cherchent refuge derrière moi n'auront pas à se mettre à genoux.", "*examine son tranchant sans perdre les alliés de vue.*" },
    ORC = { "Les ancêtres ne demanderont pas si j'ai crié fort. Ils demanderont qui j'ai protégé.", "*roule un ancien pendentif de clan entre ses doigts.*", "Une lame affûtée n'a pas besoin d'une grande histoire. Elle viendra après.", "*resserre le cuir autour du manche de sa hache.*", "J'honore mon clan en choisissant les combats qui valent la peine.", "*regarde derrière lui pour vérifier que les compagnons suivent.*", "Ceux qui se tiennent derrière moi sont la raison de mon avance.", "*se frappe la poitrine une fois et relève le menton.*" },
    TROLL = { "Si les loa regardent, autant être beau à voir, héhé.", "*pose deux petites perles d'os dans sa paume et les recompte.*", "Le vieux féticheur a dit que mon avenir serait dangereux. Très utile, mon.", "*tapote un rythme de tambour rapide sur son bouclier.*", "Les ancêtres racontent des histoires. Je leur en donne des nouvelles.", "*penche la tête comme pour écouter un tambour lointain.*", "Si mon plan échoue, appelons ça une tentative particulièrement courageuse.", "*glisse un talisman desserré sous son armure.*" },
    TAUREN = { "Une montagne parle peu. Tout le monde comprend quand elle bouge.", "*enfonce lentement un sabot dans le sol pour vérifier ses appuis.*", "Je combats pour que d'autres connaissent encore la paix des plaines.", "*caresse des doigts un ruban de souvenir tressé.*", "La Terre-Mère ne demande aucune gloire. Seulement des responsabilités.", "*regarde le ciel et respire profondément par les naseaux.*", "Qui a la force d'attendre sait quand il faut agir.", "*replace soigneusement une pierre plate à sa place.*" },
    UNDEAD = { "J'ai déjà été plus laid. Rarement avant ma mort, cela dit.", "*repousse un os de doigt dans son gant.*", "Le dernier guérisseur m'a déclaré incurable. Brave homme.", "*vérifie son épaule dans un craquement sec.*", "Je dors mal. Ce n'est plus une nouveauté depuis mes funérailles.", "*époussette une vieille boucle d'armure.*", "Quand on a vu la mort, il faut au moins garder le sens de l'humour.", "*relève les coins de sa bouche avec un grincement discret.*" },
    BLOODELF = { "Même un champ de bataille mérite un peu de beauté. Il en reçoit rarement.", "*lisse un pli de sa manche finement brodée.*", "Une épée n'est pas un bijou. Cela ne l'oblige pas à être laide.", "*ajuste sa garde d'un mouvement presque imperceptible.*", "Mes ancêtres auraient discuté mon armure. Sans doute pas mon courage.", "*regarde avec dédain une bosse dans son épaulière.*", "J'ai payé cher cette cape. L'ennemi ferait bien de garder ses distances.", "*écarte une mèche de cheveux et remet soigneusement son casque.*" },
    NEUTRAL = { "Après la bataille, tout le monde parle de victoire. Avant, seul compte qui tient.", "*vérifie son tranchant et rengaine calmement.*", "Le prochain pas est plus simple quand on sait pour qui on le fait.", "*enfonce un peu son casque et redresse les épaules.*", "Un bouclier protège seulement aussi bien que la main qui le tient.", "*parcourt lentement les rangs alliés du regard.*", "Le courage n'est pas l'absence de peur. C'est une décision.", "*ferme le poing sur sa poignée et expire lentement.*" },
}
